    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    @Column(name = "workflow_key", nullable = false)
    private Long workflowKey;

    @Column(name = "model_version_key", nullable = false)
    private Long modelVersionKey;

    @Column(name = "workflow_name", length = 1000, nullable = false)
    private String workflowName;

    @Column(name = "message_name", length = 1000, nullable = false)
    private String messageName;

    @Column(name = "event_id", length = 200)
    private String eventId;

    @Column(name = "transaction_id", length = 2000)
    private String transactionId;

    @Column(name = "workflow_filter", length = 4000)
    private String workflowFilter;

    @Column(name = "action_name", length = 200, nullable = false)
    private String actionName;

    @Column(name = "action_data_index", length = 4000)
    private String actionDataIndex;

