    /**
     * DB JPA 계층 규약에 맞게 데이터를 변환/구성합니다.
     *
     * <p>엔티티 생명주기 콜백과 컬럼 매핑 규칙을 기준으로 처리합니다.</p>
     * @param modelVersionKey 대상 키 값
     * @param workflowName DB JPA 계층 처리에 사용하는 입력 값
     * @param messageName 처리할 원본 데이터
     * @return DB JPA 계층 처리 결과
     */
    public static TcModelWorkflowEntity newEntity(long modelVersionKey, String workflowName, String messageName) {
        if (modelVersionKey <= 0) {
            throw new IllegalArgumentException("modelVersionKey must be > 0");
        }
        if (workflowName == null || workflowName.isBlank()) {
            throw new IllegalArgumentException("workflowName must not be null/blank");
        }
        if (messageName == null || messageName.isBlank()) {
            throw new IllegalArgumentException("messageName must not be null/blank");
        }
        TcModelWorkflowEntity e = new TcModelWorkflowEntity();
        e.setModelVersionKey(modelVersionKey);
        e.setWorkflowName(workflowName);
        e.setMessageName(messageName);
        return e;
    }

